// Run: node --test src/Game/GameUI/scenarioMilitary.test.js
//
// "remove region count power entirely, have it be generated by the ai for every
// country by the scenario designer and that then ships with the scenario (like
// how politics generation works except everything is relative to every other
// country it generates and it doesnt waste an entire tool call per country or
// whatever, it does 20 countries per api call)" (the owner, 2026-10-16).

import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { MILITARY_BATCH_MOST, militaryRatingRequest, readMilitaryRatings } from "../AI/militaryRating.js";
import { nextMilitaryRequest, ratedKeys, scenarioMilitaryRoster, wantsMilitaryRating, withMilitaryRatings } from "./scenarioMilitary.js";

const here = path.dirname(fileURLToPath(import.meta.url));
const read = (relative) => fs.readFileSync(path.join(here, relative), "utf8").split("\r\n").join("\n");
const FULL = { quality: 70, technology: 65, land: 75, sea: 40, air: 55, spending: 60, manpowerShare: 10, cavalryShare: 0.2, siegeShare: 0.1 };

const world = () => ({
  ownerCodes: ["Aland", "Borduria", "Cisland"],
  polityOverrides: {
    Aland: { name: "Aland", color: "#123456", population: 5e6, military: { quality: 80 } },
    Borduria: { name: "Borduria", population: 9e6, military: FULL },
    Gone: { name: "Gone", status: "dissolved" },
  },
  groups: { "The Watch": { name: "The Watch", description: "Sworn brothers on the Wall.", military: { manpowerShare: 60 } } },
});

test("the roster is every country and group of the scenario, with what is known of each", () => {
  const roster = scenarioMilitaryRoster(world());
  assert.deepEqual(roster.map((entry) => [entry.key, entry.group, entry.population]), [
    ["Aland", false, 5e6],
    ["Borduria", false, 9e6],
    ["Cisland", false, 0],
    ["The Watch", true, 0],
  ]);
  assert.equal(roster.find((entry) => entry.key === "The Watch").note, "Sworn brothers on the Wall.");
  // Borduria has everything; Aland lacks figures; Cisland and the Watch lack their people.
  assert.deepEqual(roster.map(wantsMilitaryRating), [true, false, true, true]);
});

test("a run asks of twenty at a time, shows every polity rated as the scale, and asks of each once", () => {
  const roster = scenarioMilitaryRoster(world());
  const first = nextMilitaryRequest(roster);
  assert.deepEqual(first.polities.map((entry) => entry.name), ["Aland", "Cisland", "The Watch"]);
  assert.deepEqual(first.rated.map((entry) => entry.name), ["Borduria"], "the scale: those rated, never those being rated");
  assert.equal(nextMilitaryRequest(roster, { tried: new Set(["Aland", "Cisland", "The Watch"]) }), null);
  // Again: every one, and the scale only those rated in this run.
  const again = nextMilitaryRequest(roster, { again: true });
  assert.deepEqual(again.polities.map((entry) => entry.name), ["Aland", "Borduria", "Cisland", "The Watch"]);
  assert.deepEqual(again.rated, []);
  // Nobody rated, and more than one request takes: the strongest first, from the whole list.
  const many = scenarioMilitaryRoster({ ownerCodes: Array.from({ length: 30 }, (_, at) => `Land ${at}`) });
  const picking = nextMilitaryRequest(many);
  assert.equal(picking.pickFrom.length, 30);
  assert.equal(picking.polities, undefined);
  assert.deepEqual(ratedKeys(many, [{ name: "land 4" }, { name: "Nowhere" }]), ["Land 4"]);
});

test("an answer fills in what a polity lacks, its people only where the designer gave none, and 'again' rates over", () => {
  const roster = scenarioMilitaryRoster(world());
  const ratings = [
    { name: "aland", population: 7e6, military: { quality: 40, technology: 90 } },
    { name: "Cisland", population: 3.4e6, military: FULL },
    { name: "The Watch", population: 2000, military: { quality: 75, manpowerShare: 5 } },
    { name: "Nowhere", military: FULL },
  ];
  const { world: next, written } = withMilitaryRatings(world(), roster, ratings);
  assert.deepEqual(written, ["Aland", "Cisland", "The Watch"]);
  assert.deepEqual(next.polityOverrides.Aland, { name: "Aland", color: "#123456", population: 5e6, military: { quality: 80, technology: 90 } }, "what the designer set stands");
  assert.deepEqual(next.polityOverrides.Cisland, { name: "Cisland", population: 3400000, military: FULL }, "a country with no record of its own gets one");
  assert.deepEqual(next.groups["The Watch"].military, { quality: 75, manpowerShare: 60 });
  assert.equal(next.groups["The Watch"].population, 2000);
  assert.equal(next.polityOverrides.Gone.status, "dissolved", "the rest of the world is as it was");
  // Again: over what it had (its people still the designer's).
  const over = withMilitaryRatings(world(), roster, [{ name: "Aland", population: 7e6, military: { quality: 40 } }], { again: true }).world;
  assert.deepEqual(over.polityOverrides.Aland.military, { quality: 40 });
  assert.equal(over.polityOverrides.Aland.population, 5e6);
  // A world without groups is given none.
  assert.equal("groups" in withMilitaryRatings({ ownerCodes: ["Aland"] }, scenarioMilitaryRoster({ ownerCodes: ["Aland"] }), [{ name: "Aland", military: FULL }]).world, false);
});

test("a whole run: forty-five countries in three requests, each rated against all those before it", () => {
  // An AI of the test's own: the strongest are those of the lowest number; it rates whatever it is asked.
  const strength = (name) => 90 - Number(name.split(" ")[1]);
  const answer = ({ systemPrompt, userMessage, asked, picking, most }) => {
    const names = picking ? [...asked].sort((a, b) => strength(b) - strength(a)).slice(0, most) : asked;
    return { polities: names.map((name) => ({ polity: name, population: 1e6, military: { ...FULL, quality: strength(name) } })) };
  };
  let scenario = { ownerCodes: Array.from({ length: 45 }, (_, at) => `Land ${at}`) };
  const tried = new Set();
  const requests = [];
  for (;;) {
    const roster = scenarioMilitaryRoster(scenario);
    const request = nextMilitaryRequest(roster, { tried });
    if (!request) break;
    const made = militaryRatingRequest({ ...(request.pickFrom ? { pickFrom: request.pickFrom } : { polities: request.polities }), rated: request.rated });
    requests.push({ picking: made.picking, rated: request.rated.length, userMessage: made.userMessage });
    const ratings = readMilitaryRatings(answer(made), made.asked);
    for (const key of request.pickFrom ? ratedKeys(roster, ratings) : request.wanted.map((entry) => entry.key)) tried.add(key);
    scenario = withMilitaryRatings(scenario, roster, ratings).world;
  }
  assert.deepEqual(requests.map((entry) => [entry.picking, entry.rated]), [[true, 0], [false, 20], [false, 40]]);
  assert.equal(requests.length, Math.ceil(45 / MILITARY_BATCH_MOST));
  // The first set the scale with the strongest twenty; the last was shown every one of the forty before it.
  assert.match(requests[0].userMessage, /RATE the 20 of these whose militaries are the strongest/);
  assert.match(requests[2].userMessage, /ALREADY RATED[^\n]*\n(- Land \d+: [^\n]+\n){40}/);
  assert.equal(scenarioMilitaryRoster(scenario).filter(wantsMilitaryRating).length, 0, "every country rated, its people too");
});

test("the Scenario Editor's Wars feature has the run, saving into the scenario batch by batch", () => {
  const bar = read("libraryBar.jsx");
  assert.ok(/extras=\{kind === "scenario" \? \{\s*fronts: \([\s\S]*?<ScenarioMilitaryPanel/.test(bar), "under the Wars feature in the Features tab");
  const panel = read("ScenarioMilitaryPanel.jsx");
  assert.ok(panel.includes("const ratings = await rateMilitaryBatch({"));
  assert.ok(panel.includes("const saved = await saveScenario(scenarioId, { world: next });"));
  assert.ok(panel.includes(">Rate every country</button>"));
  assert.ok(panel.includes(">Stop</button>"));
  assert.equal(panel.toLowerCase().includes("gradient"), false);
});
